    static let urlPattern = "scanify.app/nike/scan"
    static let clipName = "Scanify — Nike"
    static let clipDescription = "Scan apparel at Nike for sizing, stock, and checkout."
    static let teamName = "Scanify"
    static let touchpoint: JourneyTouchpoint = .scanify
    static let invocationSource: InvocationSource = .qrCode

    let context: ClipContext

    var body: some View {
        NikeScanifyFlowView(
            storeBranding: StoreBranding.forStoreId("nike"),
            allowedCategory: .apparel
        )
    }
}

// MARK: - Nike flow (scanner + sheet + success)

private struct NikeScanifyFlowView: View {
    let storeBranding: StoreBranding
    var allowedCategory: ProductCategory?

    @State private var scannedProduct: ScannedProduct?
    @State private var showSuccess = false
    @State private var showProductNotFound = false
    @State private var lastUnknownBarcode: String = ""
    @State private var scanHistory: [ScannedProduct] = []

    private var demoProducts: [ScannedProduct] {
        if let cat = allowedCategory {
            return ScanifyMockData.allProducts.filter { $0.category == cat }
        }
        return ScanifyMockData.allProducts
    }

    var body: some View {
        ZStack {
            if showSuccess {
                successView
                    .transition(.scale(scale: 0.95).combined(with: .opacity))
            } else {
                cameraScanner
            }
        }
        .animation(.spring(response: 0.5, dampingFraction: 0.8), value: showSuccess)
        .fullScreenCover(item: $scannedProduct) { product in
            NikeScanifySheet(
                product: product,
                storeBranding: storeBranding,
                onDismiss: { 
                    withAnimation(.spring(response: 0.4, dampingFraction: 0.85)) {
                        scannedProduct = nil 
                    }
                },
                onOrderComplete: {
                    scannedProduct = nil
                    withAnimation(.spring(response: 0.5, dampingFraction: 0.75)) { 
                        showSuccess = true 
                    }
                    DispatchQueue.main.asyncAfter(deadline: .now() + 2.5) {
                        withAnimation(.spring(response: 0.4, dampingFraction: 0.8)) { 
                            showSuccess = false 
                        }
                    }
                }
            )
            .transition(.move(edge: .bottom).combined(with: .opacity))
        }
        .alert("Product Not Found", isPresented: $showProductNotFound) {
            Button("Scan Again", role: .cancel) {}
        } message: {
            Text(productNotFoundMessage)
        }
    }

    private var productNotFoundMessage: String {
        if lastUnknownBarcode.isEmpty { return "" }
        if allowedCategory != nil {
            return "This product isn't available at \(storeBranding.displayName). Try one of the sample products below."
        }
        return "Barcode \(lastUnknownBarcode) is not in our demo database. Try one of the sample products."
    }

    private var cameraScanner: some View {
        ZStack {
            ScanifyBarcodeScannerView(
                onBarcodeScanned: { barcode in handleBarcode(barcode) },
                isActive: scannedProduct == nil && !showSuccess && !showProductNotFound
            )
            .ignoresSafeArea()

            ScannerOverlayView(storeBranding: storeBranding)
                .ignoresSafeArea()

            VStack {
                if !scanHistory.isEmpty {
                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 8) {
                            ForEach(scanHistory) { product in
                                Button { scannedProduct = product } label: {
                                    HStack(spacing: 6) {
                                        Image(systemName: product.category.icon)
                                            .font(.system(size: 10))
                                            .foregroundStyle(product.category.accentColor)
                                        Text(product.name)
                                            .font(.system(size: 11, weight: .medium))
                                            .lineLimit(1)
                                    }
                                    .foregroundStyle(.white)
                                    .padding(.horizontal, 10)
                                    .padding(.vertical, 6)
                                    .background(.white.opacity(0.15), in: .capsule)
                                    .overlay(Capsule().stroke(.white.opacity(0.2), lineWidth: 1))
                                }
                            }
                        }
                        .padding(.horizontal, 16)
                    }
                    .padding(.top, 56)
                    .transition(.move(edge: .top).combined(with: .opacity))
                }

                Spacer()

                VStack(spacing: 8) {
                    Text("Demo Products")
                        .font(.system(size: 11, weight: .semibold))
                        .foregroundStyle(.white.opacity(0.5))

                    ScrollView(.horizontal, showsIndicators: false) {
                        HStack(spacing: 8) {
                            ForEach(demoProducts) { product in
                                Button { handleBarcode(product.barcode) } label: {
                                    HStack(spacing: 6) {
                                        Image(systemName: product.category.icon)
                                            .font(.system(size: 11))
                                        Text(product.name)
                                            .font(.system(size: 11, weight: .medium))
                                            .lineLimit(1)
                                    }
                                    .foregroundStyle(.white)
                                    .padding(.horizontal, 12)
                                    .padding(.vertical, 8)
                                    .glassEffect(.regular.interactive(), in: .capsule)
                                }
                            }
                        }
                        .padding(.horizontal, 16)
                    }
                }
                .padding(.bottom, 100)
            }
        }
    }

    private func handleBarcode(_ barcode: String) {
        guard let product = ScanifyMockData.lookup(barcode: barcode) else {
            lastUnknownBarcode = barcode
            showProductNotFound = true
            return
        }
        if let allowed = allowedCategory, product.category != allowed {
            lastUnknownBarcode = barcode
            showProductNotFound = true
            return
        }
        AudioServicesPlaySystemSound(1057)
        scannedProduct = product
        withAnimation(.spring(duration: 0.3)) {
            scanHistory.removeAll { $0.barcode == product.barcode }
            scanHistory.insert(product, at: 0)
            if scanHistory.count > 5 { scanHistory = Array(scanHistory.prefix(5)) }
        }
    }

    private var successView: some View {
        VStack(spacing: 20) {
            Spacer()
            ClipSuccessOverlay(message: "Order placed!\nShipping to your address in 2-3 business days.")
            Spacer()
        }
    }
}

// MARK: - Nike sheet (apparel → InventoryView + checkout)

private struct NikeScanifySheet: View {
    let product: ScannedProduct
    let storeBranding: StoreBranding
    let onDismiss: () -> Void
    let onOrderComplete: () -> Void

    @State private var showCheckout = false
    @State private var checkoutVariant: String = ""
    @State private var showShareSheet = false

    private var shareText: String {
        "Scanify Report: \(product.name) by \(product.brand) — $\(String(format: "%.2f", product.price))"
    }

    var body: some View {
        NavigationStack {
            Group {
                if case .apparel(let data) = product.categoryData {
                    ScanifyInventoryView(product: product, data: data, accentColor: storeBranding.accentColor) { size in
                        checkoutVariant = "Size \(size)"
                        showCheckout = true
                    }
                } else {
                    EmptyView()
                }
            }
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button { onDismiss() } label: {
                        Image(systemName: "xmark.circle.fill").foregroundStyle(.secondary)
                    }
                }
                ToolbarItem(placement: .topBarTrailing) {
                    Button { showShareSheet = true } label: {
                        Image(systemName: "square.and.arrow.up")
                            .font(.system(size: 14, weight: .medium))
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
        .sheet(isPresented: $showCheckout) {
            ScanifyCheckoutView(
                product: product,
                variant: checkoutVariant,
                accentColor: storeBranding.accentColor,
                onComplete: {
                    showCheckout = false
                    onOrderComplete()
                }
            )
        }
        .sheet(isPresented: $showShareSheet) {
            ScanifyShareSheet(items: [shareText])
        }
        .presentationDetents([.large])
        .presentationDragIndicator(.visible)
    }
}

// MARK: - Nike category view (apparel: size & inventory)

struct ScanifyInventoryView: View {
    let product: ScannedProduct
    let data: ApparelData
    var accentColor: Color = .blue
    let onBuyOnline: (String) -> Void

    @State private var selectedSize: String?
    @State private var selectedColor: ColorVariant?
    @State private var deliveryMethod: DeliveryMethod = .shipping
    @State private var showingCheckout = false
    @State private var imageScale: CGFloat = 1.0
    
    enum DeliveryMethod {
        case shipping, pickup
    }
    
    private var selectedSizeData: SizeInventory? {
        guard let size = selectedSize else { return nil }
        return data.sizes.first(where: { $0.size == size })
    }
    
    private var canPurchase: Bool {
        guard let sizeData = selectedSizeData else { return false }
        return sizeData.stockStatus != .outOfStock
    }

    var body: some View {
        ZStack {
            Color(.systemBackground)
                .ignoresSafeArea()
            
            ScrollView(showsIndicators: false) {
                VStack(spacing: 0) {
                    productHero
                    productInfo
                    Spacer(minLength: 100)
                }
            }
            
            // Sticky bottom CTA
            VStack {
                Spacer()
                bottomActionBar
            }
        }
        .navigationTitle("")
        .navigationBarTitleDisplayMode(.inline)
    }

    // MARK: - Hero Product Image
    
    private var productHero: some View {
        ZStack {
            // Nike-style gradient background
            LinearGradient(
                colors: [
                    accentColor.opacity(0.05),
                    Color(.systemBackground)
                ],
                startPoint: .top,
                endPoint: .bottom
            )
            .frame(height: 420)
            
            VStack(spacing: 0) {
                // Product image
                Image(systemName: "tshirt.fill")
                    .font(.system(size: 140, weight: .light))
                    .foregroundStyle(
                        LinearGradient(
                            colors: [accentColor.opacity(0.8), accentColor.opacity(0.4)],
                            startPoint: .topLeading,
                            endPoint: .bottomTrailing
                        )
                    )
                    .scaleEffect(imageScale)
                    .animation(.spring(response: 0.6, dampingFraction: 0.7), value: imageScale)
                    .onAppear {
                        withAnimation(.spring(response: 0.8, dampingFraction: 0.6).delay(0.1)) {
                            imageScale = 1.0
                        }
                    }
                    .padding(.top, 60)
            }
            .frame(height: 420)
        }
    }
    
    // MARK: - Product Info
    
    private var productInfo: some View {
        VStack(alignment: .leading, spacing: 24) {
            // Title & Price
            VStack(alignment: .leading, spacing: 8) {
                Text(product.name)
                    .font(.system(size: 26, weight: .bold, design: .default))
                    .foregroundStyle(.primary)
                
                Text(product.brand)
                    .font(.system(size: 16, weight: .medium))
                    .foregroundStyle(.secondary)
                
                Text(String(format: "$%.2f", product.price))
                    .font(.system(size: 20, weight: .semibold))
                    .foregroundStyle(.primary)
                    .padding(.top, 4)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.horizontal, 20)
            
            Divider()
                .padding(.horizontal, 20)
            
            // Size Selection
            sizeSelectionSection
            
            // Color Selection
            if !data.colors.isEmpty {
                Divider()
                    .padding(.horizontal, 20)
                colorSelectionSection
            }
            
            Divider()
                .padding(.horizontal, 20)
            
            // Delivery Options
            deliveryOptionsSection
            
            Divider()
                .padding(.horizontal, 20)
            
            // Product Details
            productDetailsSection
            
            // Nearby Stores (if out of stock)
            if let sizeData = selectedSizeData, sizeData.stockStatus == .outOfStock {
                Divider()
                    .padding(.horizontal, 20)
                nearbyStoresSection
            }
        }
        .padding(.top, 20)
    }

    // MARK: - Size Selection Section
    
    private var sizeSelectionSection: some View {
        VStack(alignment: .leading, spacing: 16) {
            HStack {
                Text("Select Size")
                    .font(.system(size: 18, weight: .semibold))
                    .foregroundStyle(.primary)
                
                Spacer()
                
                Text(data.fit)
                    .font(.system(size: 14, weight: .medium))
                    .foregroundStyle(.secondary)
                    .padding(.horizontal, 12)
                    .padding(.vertical, 6)
                    .background(Color(.secondarySystemFill))
                    .clipShape(Capsule())
            }
            
            // Size grid
            LazyVGrid(
                columns: Array(repeating: GridItem(.flexible(), spacing: 12), count: 4),
                spacing: 12
            ) {
                ForEach(data.sizes) { sizeItem in
                    nikeSizeButton(sizeItem)
                }
            }
        }
        .padding(.horizontal, 20)
    }
    
    private func nikeSizeButton(_ item: SizeInventory) -> some View {
        Button {
            withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
                selectedSize = item.size
            }
            #if !targetEnvironment(simulator)
            let generator = UIImpactFeedbackGenerator(style: .light)
            generator.impactOccurred()
            #endif
        } label: {
            VStack(spacing: 8) {
                Text(item.size)
                    .font(.system(size: 16, weight: .semibold))
                    .foregroundStyle(
                        item.stockStatus == .outOfStock
                            ? Color(.tertiaryLabel)
                            : (selectedSize == item.size ? Color.white : Color.primary)
                    )
                
                // Stock indicator dot
                if item.stockStatus != .outOfStock {
                    Circle()
                        .fill(item.stockStatus == .lowStock ? Color.orange : Color.green)
                        .frame(width: 6, height: 6)
                        .opacity(selectedSize == item.size ? 1 : 0.6)
                }
            }
            .frame(maxWidth: .infinity)
            .frame(height: 64)
            .background(
                RoundedRectangle(cornerRadius: 8)
                    .fill(
                        selectedSize == item.size
                            ? Color.primary
                            : (item.stockStatus == .outOfStock
                                ? Color(.tertiarySystemFill)
                                : Color(.secondarySystemFill))
                    )
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8)
                    .strokeBorder(
                        selectedSize == item.size ? Color.primary : Color.clear,
                        lineWidth: 2
                    )
            )
            .opacity(item.stockStatus == .outOfStock ? 0.4 : 1.0)
        }
        .disabled(item.stockStatus == .outOfStock)
    }

    // MARK: - Color Selection Section
    
    private var colorSelectionSection: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("Select Color")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(.primary)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 16) {
                    ForEach(data.colors) { color in
                        Button {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
                                selectedColor = color
                            }
                            #if !targetEnvironment(simulator)
                            let generator = UIImpactFeedbackGenerator(style: .light)
                            generator.impactOccurred()
                            #endif
                        } label: {
                            VStack(spacing: 10) {
                                Circle()
                                    .fill(Color(scanifyHex: color.hex))
                                    .frame(width: 48, height: 48)
                                    .overlay(
                                        Circle()
                                            .strokeBorder(Color.primary, lineWidth: 2)
                                            .padding(-4)
                                            .opacity(selectedColor?.id == color.id ? 1 : 0)
                                    )
                                    .shadow(color: Color(scanifyHex: color.hex).opacity(0.3), radius: 8, y: 4)
                                
                                Text(color.name)
                                    .font(.system(size: 13, weight: .medium))
                                    .foregroundStyle(selectedColor?.id == color.id ? .primary : .secondary)
                            }
                        }
                    }
                }
                .padding(.horizontal, 20)
            }
            .padding(.horizontal, -20)
        }
        .padding(.horizontal, 20)
    }

    // MARK: - Delivery Options Section
    
    private var deliveryOptionsSection: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("How would you like to get your order?")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(.primary)
            
            VStack(spacing: 12) {
                // Shipping option
                deliveryOptionButton(
                    icon: "shippingbox.fill",
                    title: "Ship to Me",
                    subtitle: "Free shipping on orders over $50 • 2-3 business days",
                    isSelected: deliveryMethod == .shipping,
                    action: {
                        withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
                            deliveryMethod = .shipping
                        }
                        #if !targetEnvironment(simulator)
                        let generator = UIImpactFeedbackGenerator(style: .light)
                        generator.impactOccurred()
                        #endif
                    }
                )
                
                // Pickup option
                if let sizeData = selectedSizeData, sizeData.stockStatus != .outOfStock {
                    deliveryOptionButton(
                        icon: "bag.fill",
                        title: "Pick Up at Store",
                        subtitle: "Ready for pickup in 1 hour • Free",
                        isSelected: deliveryMethod == .pickup,
                        action: {
                            withAnimation(.spring(response: 0.3, dampingFraction: 0.7)) {
                                deliveryMethod = .pickup
                            }
                            #if !targetEnvironment(simulator)
                            let generator = UIImpactFeedbackGenerator(style: .light)
                            generator.impactOccurred()
                            #endif
                        }
                    )
                }
            }
        }
        .padding(.horizontal, 20)
    }
    
    private func deliveryOptionButton(
        icon: String,
        title: String,
        subtitle: String,
        isSelected: Bool,
        action: @escaping () -> Void
    ) -> some View {
        Button(action: action) {
            HStack(spacing: 16) {
                Image(systemName: icon)
                    .font(.system(size: 22))
                    .foregroundStyle(isSelected ? accentColor : .secondary)
                    .frame(width: 44, height: 44)
                    .background(
                        Circle()
                            .fill(isSelected ? accentColor.opacity(0.1) : Color(.tertiarySystemFill))
                    )
                
                VStack(alignment: .leading, spacing: 4) {
                    Text(title)
                        .font(.system(size: 16, weight: .semibold))
                        .foregroundStyle(.primary)
                    
                    Text(subtitle)
                        .font(.system(size: 13))
                        .foregroundStyle(.secondary)
                        .multilineTextAlignment(.leading)
                }
                
                Spacer()
                
                Image(systemName: isSelected ? "checkmark.circle.fill" : "circle")
                    .font(.system(size: 24))
                    .foregroundStyle(isSelected ? accentColor : Color(.tertiaryLabel))
            }
            .padding(16)
            .background(
                RoundedRectangle(cornerRadius: 12)
                    .fill(Color(.secondarySystemGroupedBackground))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 12)
                    .strokeBorder(isSelected ? accentColor : Color.clear, lineWidth: 2)
            )
        }
        .buttonStyle(.plain)
    }

    // MARK: - Product Details Section
    
    private var productDetailsSection: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("Product Details")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(.primary)
            
            VStack(spacing: 12) {
                detailRow(icon: "ruler", label: "Fit", value: data.fit)
                detailRow(icon: "leaf.fill", label: "Material", value: data.material)
            }
        }
        .padding(.horizontal, 20)
    }
    
    private func detailRow(icon: String, label: String, value: String) -> some View {
        HStack {
            Image(systemName: icon)
                .font(.system(size: 16))
                .foregroundStyle(.secondary)
                .frame(width: 24)
            
            Text(label)
                .font(.system(size: 15))
                .foregroundStyle(.secondary)
            
            Spacer()
            
            Text(value)
                .font(.system(size: 15, weight: .medium))
                .foregroundStyle(.primary)
        }
        .padding(.vertical, 12)
        .padding(.horizontal, 16)
        .background(
            RoundedRectangle(cornerRadius: 10)
                .fill(Color(.secondarySystemGroupedBackground))
        )
    }
    
    // MARK: - Nearby Stores Section
    
    private var nearbyStoresSection: some View {
        VStack(alignment: .leading, spacing: 16) {
            HStack(spacing: 8) {
                Image(systemName: "exclamationmark.triangle.fill")
                    .font(.system(size: 16))
                    .foregroundStyle(.orange)
                
                VStack(alignment: .leading, spacing: 2) {
                    Text("Out of Stock")
                        .font(.system(size: 16, weight: .semibold))
                        .foregroundStyle(.primary)
                    
                    Text("Check nearby stores or ship to your address")
                        .font(.system(size: 13))
                        .foregroundStyle(.secondary)
                }
            }
            .padding(16)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(
                RoundedRectangle(cornerRadius: 12)
                    .fill(Color.orange.opacity(0.1))
            )
            
            Text("Available Nearby")
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(.primary)

            VStack(spacing: 12) {
                nearbyStoreRow(
                    name: "Yorkdale Mall",
                    availability: "Size \(selectedSize ?? "M") available",
                    distance: "4.2 km",
                    stockColor: .green
                )
                
                nearbyStoreRow(
                    name: "Eaton Centre",
                    availability: "Low stock (2 left)",
                    distance: "6.1 km",
                    stockColor: .orange
                )
            }
        }
        .padding(.horizontal, 20)
    }
    
    private func nearbyStoreRow(name: String, availability: String, distance: String, stockColor: Color) -> some View {
        HStack(spacing: 16) {
            Image(systemName: "storefront.fill")
                .font(.system(size: 20))
                .foregroundStyle(.secondary)
                .frame(width: 44, height: 44)
                .background(
                    Circle()
                        .fill(Color(.tertiarySystemFill))
                )
            
            VStack(alignment: .leading, spacing: 4) {
                Text(name)
                    .font(.system(size: 15, weight: .medium))
                    .foregroundStyle(.primary)
                
                HStack(spacing: 6) {
                    Circle()
                        .fill(stockColor)
                        .frame(width: 6, height: 6)
                    
                    Text(availability)
                        .font(.system(size: 13))
                        .foregroundStyle(stockColor)
                }
            }
            
            Spacer()
            
            Text(distance)
                .font(.system(size: 14, weight: .medium))
                .foregroundStyle(.secondary)
        }
        .padding(16)
        .background(
            RoundedRectangle(cornerRadius: 12)
                .fill(Color(.secondarySystemGroupedBackground))
        )
    }
    
    // MARK: - Bottom Action Bar
    
    private var bottomActionBar: some View {
        VStack(spacing: 0) {
            Divider()
            
            HStack(spacing: 16) {
                // Favorite button
                Button {
                    #if !targetEnvironment(simulator)
                    let generator = UIImpactFeedbackGenerator(style: .light)
                    generator.impactOccurred()
                    #endif
                } label: {
                    Image(systemName: "heart")
                        .font(.system(size: 20))
                        .foregroundStyle(.primary)
                        .frame(width: 52, height: 52)
                        .background(
                            RoundedRectangle(cornerRadius: 26)
                                .fill(Color(.secondarySystemFill))
                        )
                }
                
                // Add to Bag button
                Button {
                    if let size = selectedSize {
                        #if !targetEnvironment(simulator)
                        let generator = UIImpactFeedbackGenerator(style: .medium)
                        generator.impactOccurred()
                        #endif
                        onBuyOnline(size)
                    }
                } label: {
                    HStack(spacing: 8) {
                        Image(systemName: "bag.fill")
                            .font(.system(size: 18, weight: .semibold))
                        
                        Text(deliveryMethod == .pickup ? "Pick Up at Store" : "Add to Bag")
                            .font(.system(size: 17, weight: .semibold))
                    }
                    .foregroundStyle(.white)
                    .frame(maxWidth: .infinity)
                    .frame(height: 52)
                    .background(
                        RoundedRectangle(cornerRadius: 26)
                            .fill(canPurchase ? Color.primary : Color(.tertiaryLabel))
                    )
                }
                .disabled(!canPurchase)
                .opacity(canPurchase ? 1.0 : 0.5)
            }
            .padding(.horizontal, 20)
            .padding(.vertical, 12)
            .background(
                Color(.systemBackground)
                    .ignoresSafeArea()
            )
        }
    }
}

// MARK: - From Submissions/scanify/company_iterations/SephoraScanifyClipExperience.swift

import SwiftUI
import AudioToolbox
import AVFoundation
import Vision

struct SephoraScanifyClipExperience: ClipExperience {
    static let urlPattern = "scanify.app/sephora/scan"
    static let clipName = "Scanify — Sephora"
    static let clipDescription = "Scan cosmetics for virtual try-on, shades, and checkout."
    static let teamName = "Scanify"
    static let touchpoint: JourneyTouchpoint = .scanify
    static let invocationSource: InvocationSource = .qrCode

    let context: ClipContext

    var body: some View {
        SephoraScanifyFlowView(
            storeBranding: StoreBranding.forStoreId("sephora"),
            allowedCategory: .cosmetics
        )
    }
}

// MARK: - Sephora flow

private struct SephoraScanifyFlowView: View {
    let storeBranding: StoreBranding
    var allowedCategory: ProductCategory?

    @State private var scannedProduct: ScannedProduct?
    @State private var showSuccess = false
    @State private var showProductNotFound = false
    @State private var lastUnknownBarcode: String = ""
    @State private var scanHistory: [ScannedProduct] = []

    private var demoProducts: [ScannedProduct] {
        if let cat = allowedCategory {
            return ScanifyMockData.allProducts.filter { $0.category == cat }
        }
        return ScanifyMockData.allProducts
    }

    var body: some View {
        ZStack {
            if showSuccess {
                successView
                    .transition(.scale.combined(with: .opacity))
            } else {
                cameraScanner
            }
        }
        .animation(.spring(duration: 0.35), value: showSuccess)
        .sheet(item: $scannedProduct) { product in
            SephoraScanifySheet(
                product: product,
                storeBranding: storeBranding,
                onDismiss: { scannedProduct = nil },
